SEEDS = [
 ('R2-333',Q,'barrierearm','unattested seed','MODEL-GENERATED, flagged. Believed in use in DE housing marketing for "partly barrier-free"; not found in any text read. Would be attested or rejected by a Land housing-subsidy guideline or a DPO statement.'),
 ('R2-333',Q,'voll rollstuhlgerecht / teilweise rollstuhlgerecht','unattested seed','MODEL-GENERATED, flagged. Believed to be the Wheelmap.org (Sozialhelden e.V.) categories; the fetch failed (403, then two Wayback connection failures, search log E12-E14), so unattested.'),
]
HDR = ['concept_id','concept_label','form','language','jurisdiction','usage_type','scope_note','attestation_tier','source','locator','quote','conflation_note']
ws = lambda s: re.sub(r'\s+', ' ', s)
txt = {}
bad = 0; n_ex = n_ws = 0
out = []
for c, lab, form, use, scope, tier, k, loc, q, conf in R:
    title, iss, url, tf, jur, pdf, kind = S[k]
    if tf not in txt: txt[tf] = open(f'{BASE}/text/{tf}', encoding='utf-8').read()
    t = txt[tf]
    if len(q.split()) > 25: print('TOO LONG', q); bad += 1
    i = t.find(q)
    if i >= 0: n_ex += 1
    elif ws(q) in ws(t):
        n_ws += 1; i = re.search(r'\s+'.join(map(re.escape, q.split())), t).start()
    else:
        print('FAIL', k, q); bad += 1; continue
    if pdf and 'p. ' not in loc:
        loc += f' (PDF p. {t[:i].count(chr(12)) + 1})'
    src = f'{title} — {iss} — {url} [text: {kind}]'
    out.append([c, lab, form, 'de', jur, use, scope, tier, src, loc, q, conf])
for c, lab, form, use, note in SEEDS:
    out.append([c, lab, form, 'de', 'DE', use, note, 'seed', '', '', '', ''])
with open(f'{BASE}/equivalents.tsv', 'w', newline='') as f:
    w = csv.writer(f, delimiter='\t', lineterminator='\n'); w.writerow(HDR); w.writerows(out)
print(f'rows {len(out)}  exact {n_ex}  ws {n_ws}  failures {bad}')
sys.exit(1 if bad else 0)
